double v_scale = std::sqrt(targetTemp / k_B);

// Generate random directions (spherical coordinates)
std::uniform_real_distribution<double> angle_dis(0.0, 2.0 * M_PI);
std::uniform_real_distribution<double> polar_dis(0.0, M_PI);

// Generate random speeds from Maxwell-Boltzmann distribution
std::uniform_real_distribution<double> speed_dis(0.0, 1.0);
auto maxwell_boltzmann_speed = [&](double v_scale) {
    double u1 = speed_dis(gen);
    double u2 = speed_dis(gen);
    return v_scale * std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);
};

