    if (dis(gen) < prob) {
        // Generate new velocity from Maxwell-Boltzmann distribution
        double speed = maxwell_boltzmann_speed(v_scale);
        double theta = polar_dis(gen);
        double phi = angle_dis(gen);

        // Convert spherical to Cartesian coordinates
        double x = speed * std::sin(theta) * std::cos(phi);
        double y = speed * std::sin(theta) * std::sin(phi);
        double z = speed * std::cos(theta);

        velocities[i] = vec3(x, y, z);
    }
}

